const cart = [
  { name: 'Pen', price: 2, inStock: true },
  { name: 'Mug', price: 8, inStock: false },
  { name: 'Bag', price: 20, inStock: true }
];

function inStockTotal(items) {
  return items
    .filter(i => i.inStock)
    .map(i => i.price)
    .reduce((sum, p) => sum + p, 0);
}

console.log(inStockTotal(cart)); // 22

